STUDENT = [{'id': 'm3b01', 'mood': 'bright', 'text': "I got it! I'm shift leader now, and I start on Monday!"}, {'id': 'm3b03', 'mood': 'bright', 'text': "She's cooking crab curry again, so I know she's really better!"}, {'id': 'm3b13', 'mood': 'bright', 'text': 'Wow, that was a long answer! Well done!'}, {'id': 'm3b14', 'mood': 'bright', 'text': 'The sunset was so pretty tonight! The whole sky was orange!'}, {'id': 'm3b16', 'mood': 'bright', 'text': 'Look at this photo! The light on the water is perfect!'}, {'id': 'm3b17', 'mood': 'bright', 'text': 'Sri Lanka won by two wickets? Sam must be going crazy!'}, {'id': 'm3b21', 'mood': 'bright', 'text': "Thirty-three days of saving, and I've got three thousand rupees!"}, {'id': 'm3b30', 'mood': 'bright', 'text': "Thenuka's getting so big! Sam showed me a photo!"}, {'id': 'm3b44', 'mood': 'bright', 'text': "You're joking! Both of you?!"}, {'id': 'm3b48', 'mood': 'bright', 'text': "Oh, nice! That's a much better word!"}, {'id': 'm3b51', 'mood': 'bright', 'text': "Yes, that's it! Say it like that every time!"}, {'id': 'm3b54', 'mood': 'bright', 'text': "The rain stopped, and there's a rainbow over the sea!"}, {'id': 'm3b56', 'mood': 'bright', 'text': "Amma's sending a box of sweets from Jaffna!"}, {'id': 'm3b59', 'mood': 'bright', 'text': "Guess what? Priya's getting a dog!"}, {'id': 'm3b65', 'mood': 'bright', 'text': "Sam's team won the match, and he took the last wicket!"}, {'id': 'm3b72', 'mood': 'bright', 'text': 'So first I was late, but then the manager said, "Don\'t worry, you\'re the best!"'}, {'id': 'm3t09', 'mood': 'bright', 'text': "Batman doesn't need a flying suit. He's just smart. Stop laughing!"}, {'id': 'm3xb11', 'mood': 'bright', 'text': 'She said yes — can you believe it?!'}, {'id': 'm3xb14', 'mood': 'bright', 'text': "I've got it — the perfect gift for Paati!"}, {'id': 'm3xb15', 'mood': 'bright', 'text': 'Two weeks — just two weeks until the trip!'}, {'id': 'm3xb23', 'mood': 'bright', 'text': 'They gave us free tickets?!'}, {'id': 'm3xb28', 'mood': 'bright', 'text': "It's FINALLY Friday!"}, {'id': 'm3xb32', 'mood': 'bright', 'text': "I can't WAIT!"}, {'id': 'm4g19b', 'mood': 'bright', 'text': "I'm going home tomorrow!"}, {'id': 'm4g20b', 'mood': 'bright', 'text': 'That was my last exam!'}, {'id': 'm3l07', 'mood': 'low', 'text': 'I keep thinking about her cooking in that small kitchen…'}, {'id': 'm3l08', 'mood': 'low', 'text': 'Oh no… that must be really hard.'}, {'id': 'm3l16', 'mood': 'low', 'text': 'It was the third time this month… and nobody thanked me.'}, {'id': 'm3l18', 'mood': 'low', 'text': "I can't believe she said that…"}, {'id': 'm3l25', 'mood': 'low', 'text': "Every time my phone rings, I'm scared it's bad news."}, {'id': 'm3l33', 'mood': 'low', 'text': 'I wonder if she still remembers my voice on the phone…'}, {'id': 'm3l39', 'mood': 'low', 'text': "I understand… it's not easy."}, {'id': 'm3l42', 'mood': 'low', 'text': 'Oh… that must have hurt.'}, {'id': 'm3l43', 'mood': 'low', 'text': 'I know… some days are just like that.'}, {'id': 'm3l49', 'mood': 'low', 'text': "It's been raining for three days, and I haven't seen the sun once."}, {'id': 'm3l52', 'mood': 'low', 'text': "I didn't do well in the test. I studied, but I forgot everything."}, {'id': 'm3l58', 'mood': 'low', 'text': "The café was so busy, and I didn't even have time for water."}, {'id': 'm3l62', 'mood': 'low', 'text': 'I know I made a mistake… and I feel terrible about it.'}, {'id': 'm3l71', 'mood': 'low', 'text': 'I waited for an hour, but in the end, nobody came.'}, {'id': 'm3xl03', 'mood': 'low', 'text': 'Is it my fault?'}, {'id': 'm3xl13', 'mood': 'low', 'text': "It's not fair!"}, {'id': 'm3xl20', 'mood': 'low', 'text': "I'm okay — really, I am."}, {'id': 'm3xl24', 'mood': 'low', 'text': "I don't know — maybe I'm just tired."}, {'id': 'm3xl40', 'mood': 'low', 'text': 'She was ALWAYS there for me.'}, {'id': 'm3xl50', 'mood': 'low', 'text': 'I just want to go home!'}, {'id': 'm3xl51', 'mood': 'low', 'text': "I can't do this anymore!"}, {'id': 'm3xl58', 'mood': 'low', 'text': 'It was my last chance!'}, {'id': 'm3xl70', 'mood': 'low', 'text': 'I only wanted ONE thing.'}, {'id': 'm4g11l', 'mood': 'low', 'text': 'He called me last night…'}, {'id': 'm4g13l', 'mood': 'low', 'text': 'We got the results…'}, {'id': 'm4g18l', 'mood': 'low', 'text': 'My brother is getting married…'}, {'id': 'm4g19l', 'mood': 'low', 'text': "I'm going home tomorrow…"}, {'id': 'm3b10', 'mood': 'normal', 'text': "I can't believe it! You actually called him?!"}, {'id': 'm3b34', 'mood': 'normal', 'text': "My manager said I'm the best shift leader they've had!"}, {'id': 'm3b44', 'mood': 'normal', 'text': "You're joking! Both of you?!"}, {'id': 'm3l02', 'mood': 'normal', 'text': "Amma says she's okay, but I can hear it in her voice…"}, {'id': 'm3l26', 'mood': 'normal', 'text': "I keep saying sorry to customers… even when it's not my fault."}, {'id': 'm3l35', 'mood': 'normal', 'text': 'I just want to hear her say my name again.'}, {'id': 'm3l59', 'mood': 'normal', 'text': "I think I'm getting a cold… my head's so heavy."}, {'id': 'm3n10', 'mood': 'normal', 'text': "When I think about it, Colombo is busy, but it's never boring."}, {'id': 'm3n17', 'mood': 'normal', 'text': 'That was clear. Now try it with "because".'}, {'id': 'm3n18', 'mood': 'normal', 'text': "Take your time. There's no rush."}, {'id': 'm3n25', 'mood': 'normal', 'text': 'Excuse me, could you please tell me where the bus stop is?'}, {'id': 'm3n38', 'mood': 'normal', 'text': "It's Sunday again."}, {'id': 'm3n72', 'mood': 'normal', 'text': 'In the end, we found the café, but it was already closed.'}, {'id': 'm3n74', 'mood': 'normal', 'text': 'My phone number ends in two, nine, seven, zero.'}, {'id': 'm3t02', 'mood': 'normal', 'text': "I said sorry twice, and he still wouldn't listen."}, {'id': 'm3t08', 'mood': 'normal', 'text': 'The Wi-Fi is down again, and I have an exam tomorrow.'}, {'id': 'm3t12', 'mood': 'normal', 'text': 'He wanted three things, he changed his order twice, and then he left.'}, {'id': 'm3t42', 'mood': 'normal', 'text': "The bus driver didn't stop. I was standing right there."}, {'id': 'm3t43', 'mood': 'normal', 'text': "Somebody parked in front of our gate, so we couldn't get out."}, {'id': 'm3t44', 'mood': 'normal', 'text': 'The shop gave me the wrong change, and then they said it was my mistake.'}, {'id': 'm3t46', 'mood': 'normal', 'text': 'I waited forty minutes for the bus, and then two came together.'}, {'id': 'm3t47', 'mood': 'normal', 'text': 'Priya used my shampoo again without asking.'}, {'id': 'm3t58', 'mood': 'normal', 'text': 'And you just let him say that?'}, {'id': 'm3t71', 'mood': 'normal', 'text': 'So I explained it twice, and he still said I was wrong.'}, {'id': 'm3xb01', 'mood': 'normal', 'text': 'Wait… is that a cake?!'}, {'id': 'm3xb22', 'mood': 'normal', 'text': 'You made this yourself?!'}, {'id': 'm3xb32', 'mood': 'normal', 'text': "I can't WAIT!"}, {'id': 'm3xb35', 'mood': 'normal', 'text': "It's done!"}, {'id': 'm3xb36', 'mood': 'normal', 'text': "You're back!"}, {'id': 'm3xl14', 'mood': 'normal', 'text': 'I should have been there!'}, {'id': 'm3xl27', 'mood': 'normal', 'text': 'You forgot again?!'}, {'id': 'm3xl28', 'mood': 'normal', 'text': 'He said that about me?!'}, {'id': 'm3xl29', 'mood': 'normal', 'text': 'They sold the old house?!'}, {'id': 'm3xl32', 'mood': 'normal', 'text': 'You knew all along?!'}, {'id': 'm3xl33', 'mood': 'normal', 'text': 'After all this time?!'}, {'id': 'm3xl35', 'mood': 'normal', 'text': 'I really TRIED.'}, {'id': 'm3xl49', 'mood': 'normal', 'text': 'No more classes…'}, {'id': 'm3xl62', 'mood': 'normal', 'text': 'I really thought he cared!'}, {'id': 'm3xl64', 'mood': 'normal', 'text': 'I just needed a hug!'}, {'id': 'm3xn10', 'mood': 'normal', 'text': 'So… what are we doing tonight?'}, {'id': 'm3xn11', 'mood': 'normal', 'text': 'Well… it depends on the weather.'}, {'id': 'm3xn13', 'mood': 'normal', 'text': "Hmm… I'd say the second one."}, {'id': 'm3xn18', 'mood': 'normal', 'text': "There's one rule — always say thank you."}, {'id': 'm3xn37', 'mood': 'normal', 'text': 'The bus stop is on the LEFT.'}, {'id': 'm3xn40', 'mood': 'normal', 'text': "It's the THIRD house on the street."}, {'id': 'm3xn45', 'mood': 'normal', 'text': 'This one is MINE.'}, {'id': 'm3xn52', 'mood': 'normal', 'text': 'Good luck tomorrow.'}, {'id': 'm3xn54', 'mood': 'normal', 'text': 'Happy birthday, Priya.'}, {'id': 'm3xn63', 'mood': 'normal', 'text': 'Say it once more.'}, {'id': 'm3xn64', 'mood': 'normal', 'text': "That's the one."}, {'id': 'm3xn65', 'mood': 'normal', 'text': 'Enjoy your meal.'}, {'id': 'm3xn71', 'mood': 'normal', 'text': "Let's see, two teas and a coffee."}, {'id': 'm3xn80', 'mood': 'normal', 'text': "You're still here?"}, {'id': 'm3xt05', 'mood': 'normal', 'text': "That's enough!"}, {'id': 'm3xt09', 'mood': 'normal', 'text': 'I said no!'}, {'id': 'm3xt32', 'mood': 'normal', 'text': 'You told my manager?!'}, {'id': 'm3xt36', 'mood': 'normal', 'text': 'You lost the keys?!'}, {'id': 'm3xt54', 'mood': 'normal', 'text': 'Wait your turn!'}, {'id': 'm3xt62', 'mood': 'normal', 'text': 'Not in my café!'}, {'id': 'm3xt63', 'mood': 'normal', 'text': 'Answer the question!'}, {'id': 'm4g11l', 'mood': 'normal', 'text': 'He called me last night…'}, {'id': 'm4g13l', 'mood': 'normal', 'text': 'We got the results…'}, {'id': 'm4g14n', 'mood': 'normal', 'text': 'I saw him at the market.'}, {'id': 'm4g14t', 'mood': 'normal', 'text': 'I saw him at the market.'}, {'id': 'm4g16b', 'mood': 'normal', 'text': 'She told me everything!'}, {'id': 'm4g19n', 'mood': 'normal', 'text': "I'm going home tomorrow."}, {'id': 'm3t01', 'mood': 'tense', 'text': "No. That was not okay. You don't speak to people like that."}, {'id': 'm3t03', 'mood': 'tense', 'text': "I'm not crying because I'm weak. I'm crying because I'm angry."}, {'id': 'm3t06', 'mood': 'tense', 'text': 'Excuse me. I was here first.'}, {'id': 'm3t10', 'mood': 'tense', 'text': 'Stop. Listen to the question first, and then answer.'}, {'id': 'm3t16', 'mood': 'tense', 'text': 'He clicked his fingers at me. Like I was a dog.'}, {'id': 'm3t19', 'mood': 'tense', 'text': "If he comes back, I'm not serving him. Someone else can."}, {'id': 'm3t27', 'mood': 'tense', 'text': "I've asked you three times now. Please answer the question."}, {'id': 'm3t29', 'mood': 'tense', 'text': "I'm sorry, but that's not my job."}, {'id': 'm3t32', 'mood': 'tense', 'text': "I'm not asking. I'm telling you."}, {'id': 'm3t34', 'mood': 'tense', 'text': 'If you have a problem, talk to me, not about me.'}, {'id': 'm3t46', 'mood': 'tense', 'text': 'I waited forty minutes for the bus, and then two came together.'}, {'id': 'm3t47', 'mood': 'tense', 'text': 'Priya used my shampoo again without asking.'}, {'id': 'm3xt08', 'mood': 'tense', 'text': 'Out of my way, please!'}, {'id': 'm3xt13', 'mood': 'tense', 'text': 'Really… again?'}, {'id': 'm3xt14', 'mood': 'tense', 'text': 'I asked you… three times.'}, {'id': 'm3xt21', 'mood': 'tense', 'text': 'You can stay — but be quiet.'}, {'id': 'm3xt22', 'mood': 'tense', 'text': "That's not the point — you lied."}, {'id': 'm3xt26', 'mood': 'tense', 'text': 'He knew — and he said nothing.'}, {'id': 'm3xt28', 'mood': 'tense', 'text': "One more word — and I'm calling the manager."}, {'id': 'm3xt32', 'mood': 'tense', 'text': 'You told my manager?!'}, {'id': 'm3xt33', 'mood': 'tense', 'text': 'They cancelled it again?!'}, {'id': 'm3xt34', 'mood': 'tense', 'text': 'You call that an apology?!'}, {'id': 'm3xt36', 'mood': 'tense', 'text': 'You lost the keys?!'}, {'id': 'm3xt42', 'mood': 'tense', 'text': 'I was HERE first.'}, {'id': 'm3xt46', 'mood': 'tense', 'text': 'Put it BACK.'}, {'id': 'm3xt50', 'mood': 'tense', 'text': "You're back?"}, {'id': 'm3xt52', 'mood': 'tense', 'text': 'No more classes?!'}, {'id': 'm3xt66', 'mood': 'tense', 'text': 'No phones at the counter!'}, {'id': 'm3xt71', 'mood': 'tense', 'text': 'Again… really?'}, {'id': 'm4g18t', 'mood': 'tense', 'text': 'My brother is getting married.'}]
